select r.id,r.recommendation_date,s.stock_code,r.rank_no,r.recommendation_score,r.buy_reference_price,r.generated_at,r.candidate_observed_at,r.strategy_version,a.execution_mode,p.status,p.calculation_version,p.next_trading_date,p.expected_session_date,p.open_return_rate,p.close_return_rate,p.max_return_rate,p.max_drawdown_rate,p.target_hit,p.stop_hit,p.target_rate,p.stop_rate from closing_recommendation r join stock s on s.id=r.stock_id join closing_recommendation_run a on a.id=r.run_id left join overnight_performance p on p.closing_recommendation_id=r.id order by r.recommendation_date,r.rank_no;
select r.id,r.recommendation_reason,r.risk_reason,r.feature_snapshot,p.expected_session_date,p.session_open,p.session_close,p.observed_through,p.evaluated_at,jsonb_array_length(p.missing_intervals::jsonb) missing_count from closing_recommendation r left join overnight_performance p on p.closing_recommendation_id=r.id where r.strategy_version='closing-recommend-v8-1500';
select id,recommendation_date,execution_mode,generated_at,completed_at,response_snapshot::jsonb->'storedCandidates' selected,response_snapshot::jsonb->'exclusionReasons' excluded from closing_recommendation_run where request_key like 'official-%';
select count(*) total,count(*) filter(where received_at is null) receipt_null,count(*) filter(where feature_snapshot::jsonb->>'occurredAt' is not null and (feature_snapshot::jsonb->>'occurredAt')::timestamptz>detected_at) feature_after_detection,count(*) filter(where (detected_at at time zone 'Asia/Seoul')::time<=time '15:00' and (feature_snapshot::jsonb->>'occurredAt')::timestamptz>(market_session_date+time '15:00') at time zone 'Asia/Seoul') after_cutoff from scanner_detection;
select r.id,count(c.id) candles,min(c.start_time) first_candle,max(c.start_time) last_candle from closing_recommendation r join overnight_performance p on p.closing_recommendation_id=r.id left join stock_candle c on c.stock_id=r.stock_id and c.timeframe='5M' and c.is_final and (c.start_time at time zone 'Asia/Seoul')::date=p.next_trading_date where p.status='COMPLETED' group by r.id order by r.id;
select count(*) rows,count(*) filter(where (candidate_observed_at at time zone 'Asia/Seoul')::time>time '15:00') after_1500,count(*) filter(where (generated_at at time zone 'Asia/Seoul')::date>recommendation_date) generated_later from closing_recommendation where strategy_version<>'closing-recommend-v8-1500';
select (start_time at time zone 'Asia/Seoul')::date d,timeframe,count(*) n from stock_candle where start_time>='2026-09-23' group by 1,2 order by 1,2;
